import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not webpage_url:
        raise requests.RequestException("Invalid URL provided.")
    try:
        url_legacy_compatible = webpage_url.startswith('http://')
        response = requests.get(webpage_url, verify=url_legacy_compatible)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table_element = tree.xpath('//table')[0] if tree.xpath('//table') else None
        if table_element is None:
            return 0
        rows = table_element.xpath('.//tr')
        data = []
        for row in rows:
            cols = row.xpath('.//td|.//th')
            if cols:
                data.append([col.text_content().strip() for col in cols])
        if not data:
            return 0
        df = pd.DataFrame(data[1:], columns=data[0] if data[0] else None)
    except Exception as e:
        raise requests.RequestException(f"Error parsing HTML: {e}")
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.commit()
        row_count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return row_count

