import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not os.path.exists(destination_directory):
        os.makedirs(destination_directory)
    local_zip_path = os.path.join(destination_directory, 'temp.zip')
    try:
        response = requests.get(url, headers=headers, stream=True)
        response.raise_for_status()
        with open(local_zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip from {url}: {e}")
    extracted_files = []
    try:
        with zipfile.ZipFile(local_zip_path, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
            extracted_files = zip_ref.namelist()
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid or corrupted zip file: {e}")
    finally:
        if os.path.exists(local_zip_path):
            os.remove(local_zip_path)
    return extracted_files

